INSERT INTO tele_sites (site_id, config) VALUES ('harborlight-vet', '{"siteId":"harborlight-vet","target":"cloudflare","specialty":"veterinary","specialtyLabel":"Veterinary clinic","businessName":"Harborlight Vet","brandName":"Harborlight Vet","location":"Quezon City, Philippines","email":"hello@harborlight.example","phone":"+63 2 8123 4567","timeZone":"Asia/Manila","theme":"brivon-dark","editorialAccent":"black","primaryColor":"#d4ff3d","accentColor":"#d4ff3d","paperColor":"#0a0a0c","fontStyle":"serif","features":{"blog":true,"gallery":true,"scheduling":true},"payments":{"gcashName":"Harborlight Vet","gcashNumber":"+63 917 555 0134","mayaName":"Harborlight Vet","mayaNumber":"+63 918 555 0142"},"customPages":[],"menuLinks":[{"id":"home","label":"Welcome","href":"/#home"},{"id":"care","label":"Our care","href":"/#care"},{"id":"about","label":"Our approach","href":"/#about"},{"id":"gallery","label":"Gallery","href":"/#gallery","feature":"gallery"},{"id":"journal","label":"Journal","href":"/#journal","feature":"blog"},{"id":"appointments","label":"Appointments","href":"/appointments.html","feature":"scheduling"},{"id":"contact","label":"Contact","href":"/#contact"}],"heroEyebrow":"A LITTLE MORE CARE, EVERY DAY","heroHeadline":"Good care for\ngood companions.","heroText":"Thoughtful veterinary care, built around the lives you share.","services":["Wellness & prevention","Gentle diagnostics","Everyday support"],"demoPosts":[{"title":"A calmer first visit starts here","slug":"a-calmer-first-visit","excerpt":"A few small things can make a new clinic visit feel easier for everyone.","category":"First visits","body":"A good first visit starts with a little time and a lot of listening. Bring any questions you have, and let us know what helps your companion feel safe. We will walk you through each step and make a plan together.","id":"sample-1","featureImageUrl":"/images/blog-welcome.svg","featureImageAlt":"An open, welcoming practice doorway","gallery":[{"imageUrl":"/images/blog-welcome.svg","altText":"An open, welcoming practice doorway","caption":"A warm welcome and time to settle in.","sortOrder":0},{"imageUrl":"/images/blog-care-team.svg","altText":"A care team listening together","caption":"Questions are always part of the visit.","sortOrder":1}],"publishedAt":"2026-10-02T17:51:22.726Z"},{"title":"The little check-ins that matter","slug":"little-check-ins-that-matter","excerpt":"Preventive care is less about doing more and more about noticing early.","category":"Everyday care","body":"Regular wellness visits give us a chance to notice small changes, answer questions, and keep a simple record of what is normal for your pet. A steady rhythm of care can make the unexpected feel a little less surprising.","id":"sample-2","featureImageUrl":"/images/blog-small-moments.svg","featureImageAlt":"A sunlit still life with a flower and warm cup","gallery":[{"imageUrl":"/images/blog-small-moments.svg","altText":"A sunlit still life with a flower and warm cup","caption":"Small routines can make care feel easier.","sortOrder":0},{"imageUrl":"/images/blog-care-team.svg","altText":"A care team ready to listen","caption":"A little check-in can open a helpful conversation.","sortOrder":1}],"publishedAt":"2026-09-23T17:51:22.726Z"},{"title":"Making room for a slower hello","slug":"a-slower-hello","excerpt":"A visit can begin at your pet’s pace. Here are a few ways we make space.","category":"Our approach","body":"Every pet arrives with a different story. We make room for a quiet introduction, a pause when it helps, and a conversation about what works best at home.","id":"sample-3","featureImageUrl":"/images/blog-care-team.svg","featureImageAlt":"A practice team and companion in a calm room","gallery":[{"imageUrl":"/images/blog-care-team.svg","altText":"A practice team and companion in a calm room","caption":"A familiar team makes space for a slower hello.","sortOrder":0},{"imageUrl":"/images/blog-welcome.svg","altText":"A welcoming room with an open doorway","caption":"The first moments can move at your pace.","sortOrder":1}],"publishedAt":"2026-09-14T17:51:22.726Z"}],"demoGallery":[{"title":"A warm welcome","imageUrl":"","altText":"Illustrated gallery placeholder for a welcoming practice space","caption":"A friendly first impression starts at the door.","category":"Practice life","sortOrder":1,"status":"published"},{"title":"Care, at every stage","imageUrl":"","altText":"Illustrated gallery placeholder for a care moment","caption":"Thoughtful care for the everyday and the unexpected.","category":"Our approach","sortOrder":2,"status":"published"},{"title":"A little time to listen","imageUrl":"","altText":"Illustrated gallery placeholder for a conversation with the care team","caption":"Questions welcome. We will take the time.","category":"Team","sortOrder":3,"status":"published"}],"createdAt":"2026-10-11T17:51:22.726Z"}'::jsonb) ON CONFLICT (site_id) DO NOTHING;
INSERT INTO tele_blog_posts (site_id, title, slug, excerpt, body, feature_image_url, feature_image_alt, category, status, published_at) VALUES ('harborlight-vet', 'A calmer first visit starts here', 'a-calmer-first-visit', 'A few small things can make a new clinic visit feel easier for everyone.', 'A good first visit starts with a little time and a lot of listening. Bring any questions you have, and let us know what helps your companion feel safe. We will walk you through each step and make a plan together.', '/images/blog-welcome.svg', 'An open, welcoming practice doorway', 'First visits', 'published', now()) ON CONFLICT (site_id, slug) DO NOTHING;
